args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-11-03-chromatin-family-trees');library(ggplot2);library(grid);library(ape);z<-readRDS(file.path(W,'tree-data.rds'));cols<-c(H2A='#159F96',H2B='#E36A55',H3='#6862B0',H4='#8A9D32');families<-names(cols)
# Verify that canonical aggregation cannot conceal cross-family canonical matches.
canonical<-c('H2A','H2B','H3','H4');bad<-z$marks[z$marks$evidence_class %in% canonical & z$marks$family!=z$marks$evidence_class,];stopifnot(nrow(bad)==0)
# Three independent binary columns retain all simultaneous reference-class matches.
rail<-merge(z$tips, data.frame(reference=c('Canonical','H2A.Z','macroH2A'),col=1:3),by=NULL);rail$matched<-FALSE
for(i in seq_len(nrow(rail))){h<-rail$family[i];cl<-if(rail$reference[i]=='Canonical')h else if(rail$reference[i]=='H2A.Z')'H2AZ'else'macroH2A';rail$matched[i]<-any(z$marks$family==h & z$marks$protein_id==rail$protein_id[i]&z$marks$evidence_class==cl)}
stopifnot(sum(rail$matched)==nrow(z$marks),sum(tapply(rail$matched,paste(rail$family,rail$protein_id),sum)>1)==6)
# Physical layout estimate for exploration: 81.5mm panel, >2mm data-to-track gap.
panel_mm<-(183-12-8)/2;rail_gap_mm<-2.6;rail_width_mm<-1.1;rail_pitch_mm<-2.7;rail_total_mm<-2*rail_pitch_mm+rail_width_mm;right_mm<-1.2;tree_mm<-(panel_mm-rail_gap_mm-rail_total_mm-right_mm)/1.015
st<-z$stats;st$u<-st$xmax/tree_mm;st$rail_start<-st$xmax+rail_gap_mm*st$u;st$end<-st$rail_start+rail_total_mm*st$u+right_mm*st$u;st$scale_y<- -st$tips*.04;st$scale_text_y<- -st$tips*.073;st$header_y<-st$tips*1.075;st$count<-paste0(format(st$tips,big.mark=',',trim=TRUE),' tips')
rail<-merge(rail,st[c('family','u','rail_start')],by='family',sort=FALSE);rail$xmin<-rail$rail_start+(rail$col-1)*rail_pitch_mm*rail$u;rail$xmax<-rail$xmin+rail_width_mm*rail$u;rail$ymin<-rail$y-.45;rail$ymax<-rail$y+.45
headers<-merge(st, data.frame(col=1:3,label=c('C','Z','M')),by=NULL);headers$x<-headers$rail_start+(headers$col-1)*rail_pitch_mm*headers$u+rail_width_mm*headers$u/2
# Branch depth display is determined by existing descendant counts, not new inference.
edge<-z$edges;vert<-z$verts
for(h in families){tr<-z$trees[[h]];nn<-Ntip(tr);nc<-rep(NA_integer_,nn+Nnode(tr));nc[seq_len(nn)]<-1L;count<-function(k){if(!is.na(nc[k]))return(nc[k]);v<-sum(vapply(tr$edge[tr$edge[,1]==k,2],count,integer(1)));nc[k]<<-v;v};count(nn+1L);edge$branch_role[edge$family==h]<-ifelse(nc[edge$child[edge$family==h]]>=32,'trunk','terminal');vert$branch_role[vert$family==h]<-ifelse(nc[vert$parent[vert$family==h]]>=32,'trunk','terminal')}
mix<-function(cc,other,w){v<-(1-w)*col2rgb(cc)+w*col2rgb(other);rgb(v[1,]/255,v[2,]/255,v[3,]/255)};dark<-setNames(vapply(cols,mix,character(1),other='#273D50',w=.3),families);light<-setNames(vapply(cols,mix,character(1),other='#FFFFFF',w=.32),families)
edge$ink<-ifelse(edge$branch_role=='trunk',dark[edge$family],light[edge$family]);vert$ink<-ifelse(vert$branch_role=='trunk',dark[vert$family],light[vert$family]);rail$ink<-ifelse(rail$matched,unname(dark[rail$family]),'#EDF1F2');st$ink<-unname(dark[st$family]);for(k in c('edge','vert','rail','st','headers')){v<-get(k);v$family<-factor(v$family,levels=families);assign(k,v)}
legend_data<-data.frame(family=factor('H2A',levels=families),x=NA_real_,y=NA_real_,reference=factor(c('C  Canonical','Z  H2A.Z','M  macroH2A'),levels=c('C  Canonical','Z  H2A.Z','M  macroH2A')))
p<-ggplot()+geom_segment(data=edge,aes(x=x,y=y,xend=xend,yend=yend,colour=I(ink),linewidth=branch_role),lineend='round')+geom_segment(data=vert,aes(x=x,y=y,xend=xend,yend=yend,colour=I(ink),linewidth=branch_role),lineend='round')+scale_linewidth_manual(values=c(trunk=.19,terminal=.12),guide='none')+geom_rect(data=rail,aes(xmin=xmin,xmax=xmax,ymin=ymin,ymax=ymax,fill=I(ink)),colour=NA)+geom_text(data=st,aes(x=0,y=header_y,label=family,colour=I(ink)),hjust=0,vjust=0,size=9*25.4/72,family='Arial',fontface='bold')+geom_text(data=st,aes(x=xmax,y=header_y,label=count),hjust=1,vjust=0,size=7*25.4/72,family='Arial',colour='#576572')+geom_text(data=headers,aes(x=x,y=header_y,label=label),hjust=.5,vjust=0,size=7*25.4/72,family='Arial',colour='#273D50')+geom_segment(data=st,aes(x=0,xend=.5,y=scale_y,yend=scale_y),colour='#273D50',linewidth=.35)+geom_text(data=st,aes(x=.25,y=scale_text_y,label='0.5'),size=7*25.4/72,family='Arial',colour='#273D50')+geom_point(data=legend_data,aes(x,y,shape=reference),colour='#273D50',size=1.3,na.rm=TRUE)+scale_shape_manual(values=c('C  Canonical'=15,'Z  H2A.Z'=15,'M  macroH2A'=15),name='Proteomics match',drop=FALSE)+geom_blank(data=st,aes(x=end,y=tips*1.15))+geom_blank(data=st,aes(x=-xmax*.015,y=-tips*.11))+facet_wrap(~family,ncol=2,scales='free')+scale_x_continuous(expand=c(0,0))+scale_y_continuous(expand=c(0,0))+labs(x='Substitutions per site',y=NULL)+theme_void(base_family='Arial',base_size=7)+theme(strip.text=element_blank(),panel.spacing.x=unit(8,'mm'),panel.spacing.y=unit(6,'mm'),axis.title.x=element_text(size=7,colour='#576572',margin=margin(t=3)),legend.position='top',legend.direction='horizontal',legend.title=element_text(size=7,colour='#273D50'),legend.text=element_text(size=7,colour='#273D50'),legend.key.width=unit(3,'mm'),legend.key.height=unit(4,'mm'),legend.margin=margin(0,0,4,0),legend.spacing.x=unit(1,'mm'),plot.margin=margin(5,6,5,6,unit='mm'))+guides(shape=guide_legend(nrow=1))

